class Solution {
    public List<List<Integer>> combinationSum3(int k,int n){
        List<List<Integer>> answer=new ArrayList<>();
        dfs(1,k,n,new ArrayList<>(),answer);
        return answer;
    }
    private void dfs(int start,int k,int remaining,List<Integer> path,List<List<Integer>> answer){
        if(path.size()==k){
            if(remaining==0)answer.add(new ArrayList<>(path));
            return;
        }
        for(int value=start;value<=9&&value<=remaining;value++){
            path.add(value);
            dfs(value+1,k,remaining-value,path,answer);
            path.remove(path.size()-1);
        }
    }
}

code.kotlin:
class Solution {
    fun combinationSum3(k:Int,n:Int):List<List<Int>>{
        val answer=mutableListOf<List<Int>>();
        val path=mutableListOf<Int>();
        fun dfs(start:Int,remaining:Int){
            if(path.size==k){
                if(remaining==0)answer.add(path.toList());
                return
            };
            for(value in start..9){
                if(value>remaining)break;
                path.add(value);
                dfs(value+1,remaining-value);
                path.removeAt(path.lastIndex)
            }
        };
        dfs(1,n);
        return answer
    }
}

